<?php namespace Workspace;
$hidden=static function(string $act)use($p,$card){formFields($act);echo '<input type="hidden" name="project_id" value="'.h($p).'">';if($card)echo '<input type="hidden" name="id" value="'.h($card['id']).'"><input type="hidden" name="version" value="'.h($card['version']).'">';};
$terms=static function(?array $r)use($members,$mainPdfs,$today){?>
<label>Название<input name="title" required maxlength="180" value="<?= h($r['title']??'') ?>"></label>
<label>Ответственный<select name="responsible_id" required><?php selectOptions($members,$r['responsible_id']??null) ?></select></label>
<?php foreach(['seller_signer'=>'Представитель нашей стороны','seller_authority'=>'Основание полномочий нашей стороны','buyer_signer'=>'Представитель контрагента','buyer_authority'=>'Основание полномочий контрагента'] as $k=>$label): ?><label><?= h($label) ?><input name="<?= h($k) ?>" required maxlength="<?= str_ends_with($k,'authority')?500:180 ?>" value="<?= h($r[$k]??'') ?>"></label><?php endforeach ?>
<label>Валюта<select name="currency"><?php selectOptions(array_combine(CURRENCIES,CURRENCIES),$r['currency']??'EUR') ?></select></label><label>Стоимость (0 для безвозмездного)<input name="amount" inputmode="decimal" required value="<?= h(money((int)($r['amount_minor']??0),false)) ?>"></label>
<?php foreach(['signed_on'=>'Дата подписания','starts_on'=>'Начало действия','ends_on'=>'Окончание','notice_on'=>'Крайний срок уведомления о продлении'] as $k=>$label): ?><label><?= h($label) ?><input type="date" name="<?= h($k) ?>" required value="<?= h($r[$k]??($k==='signed_on'||$k==='starts_on'?$today:'')) ?>"></label><?php endforeach ?>
<label>Условия продления<input name="renewal_terms" maxlength="1000" required value="<?= h($r['renewal_terms']??'') ?>"></label><label>Основной PDF (точная редакция)<select name="document" required><?php selectOptions($mainPdfs,$r?$r['document_id'].':'.$r['document_revision']:null) ?></select></label>
<?php }; ?>
<p class="lede">Карточки договоров, зафиксированные редакции, сроки уведомления и обязательства. Фиксация вступления в силу не является электронной подписью.</p>
<form method="get" class="filters"><input type="hidden" name="p" value="contracts"><label>Проект<select name="project"><option value="">Все проекты</option><?php selectOptions($projects,$p) ?></select></label><button>Открыть</button></form>
<?php if($p): ?><p><a href="<?= h(url('documents',['project'=>$p])) ?>">Загрузить PDF / история документов</a> · <a href="<?= h(url('contracts',['project'=>$p])) ?>">Все договоры проекта</a></p><?php endif ?>
<?php if($writable&&!$card): ?><?php if($mainPdfs&&$members&&$sellers&&$buyers): ?><details class="editor"><summary>Создать карточку</summary><form method="post" class="formgrid"><?php $hidden('contract.create') ?><label>Номер договора<input name="reference" maxlength="120" required></label><label>Наше юрлицо<select name="entity_id" required><?php selectOptions($sellers) ?></select></label><label>Контрагент<select name="counterparty_id" required><?php selectOptions($buyers) ?></select></label><?php $terms(null) ?><div class="formend"><button>Создать черновик</button></div></form></details><?php else: ?><p class="notice">Для новой карточки нужны юрлицо, контрагент, ответственный с юридическими правами и PDF договора.</p><?php endif;endif ?>
<?php if($card): ?><section class="panel"><h2>Договор <?= h($card['reference']) ?> · <?= h(($active??$latest)['title']) ?></h2><p><?= h(contractStatus($active,$today)) ?><?= $active?' · действующая редакция v'.h($active['revision']):'' ?><?= $latest['activated_at']===null?' · ожидает фиксации v'.h($latest['revision']):'' ?></p>
<?php if($writable&&$members&&$mainPdfs): ?><details class="editor"><summary>Подготовить новую редакцию</summary><p>Прежние редакции и приложения сохраняются. Приложения к новой редакции выбираются заново.</p><form method="post" class="formgrid"><?php $hidden('contract.revise');$terms($latest) ?><div class="formend"><button>Создать новую редакцию</button></div></form></details><?php endif ?>
<?php foreach($revisions as $r):$snapshot=json_decode($r['party_snapshot'],true,512,JSON_THROW_ON_ERROR);$draft=(int)$latest['id']===(int)$r['id']&&$r['activated_at']===null; ?><details <?= $draft||($active&&(int)$active['id']===(int)$r['id'])?'open':'' ?>><summary>v<?= h($r['revision']) ?> · <?= h($r['title']) ?> · <?= $r['activated_at']!==null?'Зафиксирована':($draft?'Черновик':'Заменённый черновик') ?></summary>
<p><strong>Стороны:</strong> <?= h($snapshot['seller']['name']) ?> · <?= h($snapshot['seller']['registration']) ?> · <?= h($snapshot['seller']['address']) ?> / <?= h($snapshot['buyer']['name']) ?> · <?= h($snapshot['buyer']['registration']) ?></p>
