<?php if($r['activated_at']!==null): ?><p>Зафиксировано <?= h(gmdate('Y-m-d H:i:s',(int)$r['activated_at'])) ?> UTC · пользователь #<?= h($r['activated_by']) ?> · <?= h($r['activation_note']) ?></p><?php endif ?>
<p><a href="<?= h(url('download',['id'=>$r['document_id'],'v'=>$r['document_revision']])) ?>">Основной PDF v<?= h($r['document_revision']) ?></a> · <a href="<?= h(url('document',['id'=>$r['document_id']])) ?>">История исходного документа</a></p><code><?= h($r['document_hash']) ?></code>
<h3>Приложения</h3><?php foreach($r['attachments'] as $a): ?><p><a href="<?= h(url('download',['id'=>$a['document_id'],'v'=>$a['document_revision']])) ?>"><?= h($a['label']) ?> · <?= h($a['title']) ?> v<?= h($a['document_revision']) ?></a> · <code><?= h($a['document_hash']) ?></code></p><?php if($draft&&$writable): ?><form method="post"><?php $hidden('contract.detach') ?><input type="hidden" name="attachment_id" value="<?= h($a['id']) ?>"><button class="secondary">Убрать из черновика</button></form><?php endif;endforeach ?>
<?php if($draft&&$writable&&$pdfs): ?><form method="post" class="formgrid"><?php $hidden('contract.attach') ?><label>Приложение<select name="document"><?php selectOptions($pdfs) ?></select></label><label>Название<input name="label" maxlength="180" required></label><button>Добавить</button></form><?php endif ?>
<?php if($draft&&$owner): ?><form method="post" class="formgrid"><?php $hidden('contract.activate') ?><label>Основание (подписанный документ, подтверждение полномочий)<input name="reason" required maxlength="500"></label><button>Зафиксировать вступление в силу</button></form><?php endif ?></details><?php endforeach ?></section>
<section class="panel"><h2>Обязательства</h2><?php if($writable&&$active): ?><form method="post" class="formgrid"><?php $hidden('contract.obligation') ?><label>Обязательство<input name="title" maxlength="180" required></label><label>Срок<input name="due_on" type="date" required></label><?php if($owner): ?><label>Счёт (необязательно)<select name="invoice_id"><option value="">Нет</option><?php selectOptions($invoiceOptions) ?></select></label><label>Или план платежа<select name="plan_id"><option value="">Нет</option><?php selectOptions($planOptions) ?></select></label><p>Только один источник; связь не создаёт платежей.</p><?php endif ?><button>Добавить обязательство</button></form><?php endif ?>
<?php foreach($obligations as $o): ?><details open><summary><?= h($o['title']) ?> · <?= h($o['due_on']) ?> · <?= h(['open'=>'Открыто','completed'=>'Исполнено','cancelled'=>'Отменено'][$o['state']]) ?><?= $o['state']==='open'&&$o['due_on']<$today?' · просрочено':'' ?></summary><?php if($o['invoice_id']||$o['plan_id']): ?><p>Финансовая связь: <?php if($finance):$s=$o['settlement']; ?><a href="<?= h($o['invoice_id']?url('invoices',['project'=>$p,'id'=>$o['invoice_id']]):url('economics',['project'=>$p])) ?>"><?= h($s['label']) ?></a> · остаток <?= h(money((int)$s['remaining']).' '.$s['currency']) ?> · <?= h($s['state']) ?><?= $o['state']==='completed'&&!$s['settled']?' · финансовое состояние изменилось, требуется сверка':'' ?><?php else: ?>Доступно финансовым ролям<?php endif ?></p><?php endif ?><?php if($o['decision_note']!==null): ?><p><?= h($o['decision_note']) ?> · #<?= h($o['decided_by']) ?> · <?= h(gmdate('Y-m-d H:i:s',(int)$o['decided_at'])) ?> UTC</p><?php endif ?><?php if($writable&&$o['state']==='open'&&($owner||(!$o['invoice_id']&&!$o['plan_id']))): ?><form method="post" class="formgrid"><?php $hidden('contract.decide') ?><input type="hidden" name="obligation_id" value="<?= h($o['id']) ?>"><label>Решение<select name="state"><option value="completed">Исполнено</option><option value="cancelled">Отменено</option></select></label><label>Подтверждение / причина<input name="reason" required maxlength="500"></label><button>Сохранить решение</button></form><?php endif ?></details><?php endforeach ?></section><?php endif ?>
<section class="panel"><h2>Реестр договоров</h2><div class="tablewrap"><table><thead><tr><th>Договор</th><th>Проект</th><th>Состояние</th><th>Уведомление</th><th>Окончание</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><a href="<?= h(url('contracts',['project'=>$r['project_id'],'id'=>$r['id']])) ?>"><?= h($r['reference'].' · '.($r['active']??$r['latest'])['title']) ?></a></td><td><?= h($r['project_title']) ?></td><td><?= h(contractStatus($r['active'],$today)) ?></td><td><?= h($r['active']['notice_on']??'—') ?></td><td><?= h($r['active']['ends_on']??'—') ?></td></tr><?php endforeach ?></tbody></table></div><?php if($nextBefore): ?><a href="<?= h(url('contracts',['project'=>$p,'before'=>$nextBefore])) ?>">Следующая страница</a><?php endif ?></section>
